  const err = new Error(message);
  err.code = 'INVALID_PARAMS';
  return err;
}

function invalidCursor(message = 'invalid cursor') {
  const err = new Error(message);
  err.code = 'INVALID_CURSOR';
  return err;
}

// Encode an offset into an opaque cursor token.
function encodeCursor(offset) {
  const payload = JSON.stringify({ offset, v: 1 });
  return Buffer.from(payload, 'utf8').toString('base64');
}

// Decode and validate a cursor token. Throws INVALID_CURSOR on any problem.
function decodeCursor(cursor, total) {
  if (typeof cursor !== 'string' || cursor.length === 0) {
    throw invalidCursor('cursor must be a non-empty string');
