  let payload;
  try {
    payload = JSON.parse(Buffer.from(cursor, 'base64').toString('utf8'));
  } catch {
    throw invalidCursor('cursor is not a valid token');
  }
  if (
    !payload ||
    typeof payload !== 'object' ||
    typeof payload.offset !== 'number' ||
    !Number.isInteger(payload.offset) ||
    payload.offset < 0 ||
    payload.offset >= total
  ) {
    // Either malformed or points past the last available row (stale).
    throw invalidCursor('cursor is stale or invalid');
  }
  return payload.offset;
}

