import { listTools, callTool } from "./server.mjs";

function show(label, p) {
  return Promise.resolve(p)
    .then(r => console.log(label, "OK", JSON.stringify(r)))
    .catch(e => console.log(label, "ERR", e.code, "::", e.message));
}

console.log("TOOLS:", JSON.stringify(await listTools()));

// Page 1
const r1 = await callTool("page", { limit: 2 });
console.log("page1:", r1.content[0].text);
const c1 = JSON.parse(r1.content[0].text).next_cursor;
console.log("cursor1:", c1);

// Page 2 from cursor
const r2 = await callTool("page", { limit: 2, cursor: c1 });
console.log("page2:", r2.content[0].text);

// limit out of range
await show("limit0", callTool("page", { limit: 0 }));
await show("limit3", callTool("page", { limit: 3 }));
await show("limit-missing", callTool("page", {}));
await show("limit-string", callTool("page", { limit: "2" }));

// unknown args
await show("unknown-arg", callTool("page", { limit: 1, bogus: true }));

// invalid cursors
await show("cursor-garbage", callTool("page", { limit: 1, cursor: "garbage" }));
await show("cursor-empty", callTool("page", { limit: 1, cursor: "" }));
