import { Buffer } from "node:buffer";
const stale = Buffer.from(JSON.stringify({ offset: 99, v: 1 })).toString("base64");
await show("cursor-stale", callTool("page", { limit: 1, cursor: stale }));

// unknown tool
await show("unknown-tool", callTool("nope", { limit: 1 }));
